fs = open("region.fasta").read()
seq = "".join(l.strip() for l in fs.split("\n") if not l.startswith(">"))
L=len(seq)
# longest exact direct repeat (proper suffix-doubling-free check with dict)
best=[]
for k in range(50, 8, -1):
    d={}
    hits=[]
    for i in range(L-k+1):
        km=seq[i:i+k]
        if km in d: hits.append((d[km], i, k, km))
        else: d[km]=i
    if hits:
        best=hits; break
print("longest exact direct repeat:")
for a,b,k,km in best:
    print(f"  len {k} at {a+1} and {b+1}: {km} (id 100%)")

# longest palindrome (reverse-complement match inside seq, non-overlapping halves)
comp=str.maketrans("ACGT","TGCA")
rcq=seq.translate(comp)[::-1]
bestpal=[]
for k in range(50, 8, -1):
    d={}
    hits=[]
    for i in range(L-k+1):
        km=rcq[i:i+k]           # this is revcomp of fwd segment (L-i-k .. L-i-1)
        fwd_start = L-(i+k)     # 0-based start on fwd of that segment
        if km in d: hits.append((d[km], fwd_start, k, km)); 
        else: d[km]=fwd_start
    if hits: bestpal=hits; break
print("\nlongest palindrome (arm = exact direct repeat in fwd of a segment and its own revcomp):")
for r in bestpal:
    print(" ", r)

